347	    schema: &SchemaRef,
348	    input: &Arc<dyn ExecutionPlan>,
349	    window_exprs: &[Arc<dyn WindowExpr>],
350	) -> Result<EquivalenceProperties> {
351	    // We need to update the schema, so we can't directly use input's equivalence
352	    // properties.
353	    let mut window_eq_properties = EquivalenceProperties::new(Arc::clone(schema))
354	        .extend(input.equivalence_properties().clone())?;
355	
356	    let window_schema_len = schema.fields.len();
357	    let input_schema_len = window_schema_len - window_exprs.len();
358	    let window_expr_indices = (input_schema_len..window_schema_len).collect::<Vec<_>>();
359	
360	    for (i, expr) in window_exprs.iter().enumerate() {
361	        let partitioning_exprs = expr.partition_by();
362	        let no_partitioning = partitioning_exprs.is_empty();
363	        // Collect columns defining partitioning, and construct all `SortOptions`
364	        // variations for them. Then, we will check each one whether it satisfies
365	        // the existing ordering provided by the input plan.
366	        let mut all_satisfied_lexs = vec![];
367	        for lex in partitioning_exprs
368	            .iter()
369	            .map(|pb_order| sort_options_resolving_constant(Arc::clone(pb_order)))
370	            .multi_cartesian_product()
371	            .filter_map(LexOrdering::new)
372	        {
373	            if window_eq_properties.ordering_satisfy(lex.clone())? {
374	                all_satisfied_lexs.push(lex);
375	            }
376	        }
377	        // If there is a partitioning, and no possible ordering cannot satisfy
378	        // the input plan's orderings, then we cannot further introduce any
379	        // new orderings for the window plan.
380	        if !no_partitioning && all_satisfied_lexs.is_empty() {
381	            return Ok(window_eq_properties);
382	        } else if let Some(std_expr) = expr.as_any().downcast_ref::<StandardWindowExpr>()
383	        {
384	            std_expr.add_equal_orderings(&mut window_eq_properties)?;
385	        } else if let Some(plain_expr) =
386	            expr.as_any().downcast_ref::<PlainAggregateWindowExpr>()
387	        {
388	            // We are dealing with plain window frames; i.e. frames having an
389	            // unbounded starting point.
390	            // First, check if the frame covers the whole table:
391	            if plain_expr.get_window_frame().end_bound.is_unbounded() {
392	                let window_col =
393	                    Arc::new(Column::new(expr.name(), i + input_schema_len)) as _;
394	                if no_partitioning {
395	                    // Window function has a constant result across the table:
396	                    window_eq_properties
397	                        .add_constants(std::iter::once(ConstExpr::from(window_col)))?
398	                } else {
399	                    // Window function results in a partial constant value in
400	                    // some ordering. Adjust the ordering equivalences accordingly:
