402	                        let new_partial_consts =
403	                            sort_options_resolving_constant(Arc::clone(&window_col));
404	
405	                        new_partial_consts.into_iter().map(move |partial| {
406	                            let mut existing = lex.clone();
407	                            existing.push(partial);
408	                            existing
409	                        })
410	                    });
411	                    window_eq_properties.add_orderings(new_lexs);
412	                }
413	            } else {
414	                // The window frame is ever expanding, so set monotonicity comes
415	                // into play.
416	                plain_expr.add_equal_orderings(
